import { useState } from 'react';
import { useApp } from '../state/AppContext';
import { Button, Callout, Empty, Field, Modal, Pill, SectionHead } from '../components/ui';

export function Projects(): JSX.Element {
  const { projects, newProject, removeProject, openProject, apiOnline, me } = useApp();
  const [creating, setCreating] = useState(false);
  const [title, setTitle] = useState('');
  const [busy, setBusy] = useState(false);

  const create = async () => {
    setBusy(true);
    try {
      const p = await newProject(title);
      setCreating(false);
      setTitle('');
      openProject(p.id);
    } finally {
      setBusy(false);
    }
  };

  return (
    <>
      <div className="page-head">
        <div className="eyebrow">Workspace / Projects</div>
        <h1 className="page-title display">最近项目</h1>
        <p className="page-lede">
          项目包含原始文稿、分镜 JSON、时间线、素材关联、预算与生成任务。当前保存在本机 IndexedDB；登录并同步后才会进入你的云端工作空间。
        </p>
      </div>

      {!apiOnline || !me || me.isGuest ? (
        <Callout neutral>
          <strong>本地模式。</strong> Worker 未连接或尚未登录，项目仅存于此浏览器，不会访问任何其他用户的云端项目。
          云端同步会在 OAuth 凭据配置完成后启用。
        </Callout>
      ) : (
        <Callout neutral><strong>已连接云端工作空间。</strong>所有查询同时按 user_id 与 workspace_id 过滤。</Callout>
      )}

      <SectionHead num="01" title="项目列表" aside={`${projects.length} 个项目`} />
      <div style={{ marginBottom: 18 }}>
        <Button variant="primary" onClick={() => setCreating(true)}>+ 新建项目</Button>
      </div>

      {projects.length === 0 ? (
        <Empty title="还没有项目" desc="创建一个项目后即可录入口播文稿、选择模型、设定预算并进入 AI VIDEO STUDIO。" action={<Button variant="primary" size="sm" onClick={() => setCreating(true)}>新建项目</Button>} />
      ) : (
        <div>
          {projects.map((p) => (
            <div className="row" key={p.id}>
              <div className="row-main">
                <div className="row-name">{p.title} <Pill>{p.status}</Pill> {p.storyboard ? <Pill tone="ok">有分镜</Pill> : null}</div>
                <div className="row-meta">{p.id} · 更新于 {new Date(p.updatedAt).toLocaleString('zh-CN')} · 文稿 {p.script.length} 字符</div>
              </div>
              <div className="row-actions">
                <Button size="sm" variant="primary" onClick={() => openProject(p.id)}>打开</Button>
                <Button size="sm" variant="danger" onClick={() => { if (window.confirm(`删除项目「${p.title}」？此操作不可撤销。`)) void removeProject(p.id); }}>删除</Button>
              </div>
            </div>
          ))}
        </div>
      )}

      {creating ? (
        <Modal
          title="新建项目"
          sub="创建后可立即录入口播文稿。原始文稿会被完整保留，不会被 AI 擅自删改。"
          onClose={() => setCreating(false)}
          footer={<><Button onClick={() => setCreating(false)}>取消</Button><Button variant="primary" disabled={busy} onClick={() => void create()}>创建</Button></>}
        >
          <Field label="项目名称"><input className="input" autoFocus value={title} onChange={(e) => setTitle(e.target.value)} placeholder="例如：产品发布口播视频" onKeyDown={(e) => e.key === 'Enter' && void create()} /></Field>
        </Modal>
      ) : null}

      <div className="notice">
        工程包规范（Phase 6 实现完整导出/导入）：project.json · script.md · storyboard.json · assets/{'{audio,video,images,music,effects}'} · subtitles/ · prompts/ · exports/final.mp4 · metadata.json。
        目前仅支持项目元数据与文稿的本地保存，不提供伪造的工程包。
      </div>
    </>
  );
}
