/**
 * BYOK vault lifecycle.
 *
 * Encrypted blob  -> IndexedDB (durable)
 * Plaintext keys  -> memory ONLY while unlocked
 * Password        -> memory ONLY while unlocked (needed to re-encrypt on edit)
 *
 * No plaintext key is ever written to localStorage, sessionStorage, a cookie,
 * or the server. On reload the vault is locked again and must be unlocked to
 * re-use a stored key — including when polling a previously created async
 * video task by task_id.
 */

import { decryptVault, encryptVault, isVaultFile, reencryptVault, VaultError, type VaultFile } from './crypto';
import { idbDelete, idbGet, idbSet, STORE_VAULT, VAULT_KEY } from './idb';

export interface ProviderSecret {
  apiKey: string;
  /** Optional extra upstream headers, e.g. a custom gateway's tenant header. */
  extraHeaders?: Record<string, string>;
}

export interface VaultPayload {
  secrets: Record<string, ProviderSecret>;
}

const EMPTY: VaultPayload = { secrets: {} };

export class Vault {
  private file: VaultFile | null = null;
  private password: string | null = null;
  private payload: VaultPayload = EMPTY;

  async initialize(): Promise<void> {
    const stored = await idbGet<unknown>(STORE_VAULT, VAULT_KEY);
    this.file = stored && isVaultFile(stored) ? stored : null;
  }

  get exists(): boolean {
    return this.file !== null;
  }
  get unlocked(): boolean {
    return this.password !== null;
  }
  get updatedAt(): string | null {
    return this.file?.updatedAt ?? null;
  }
  /** IDs of providers that currently have a stored key. Never returns the key itself. */
  get storedProviderIds(): string[] {
    return Object.keys(this.payload.secrets);
  }

  async create(password: string): Promise<void> {
    if (password.length < 8) throw new VaultError('EMPTY_PASSWORD', '密码至少需要 8 个字符。');
    this.file = await encryptVault<VaultPayload>(password, EMPTY);
    this.password = password;
    this.payload = { secrets: {} };
    await this.persist();
  }

  async unlock(password: string): Promise<void> {
    if (!this.file) throw new VaultError('CORRUPT_VAULT', '本机没有找到加密保险库。');
    this.payload = await decryptVault<VaultPayload>(password, this.file);
    if (!this.payload || typeof this.payload.secrets !== 'object') throw new VaultError('CORRUPT_VAULT', '保险库内容格式异常。');
    this.password = password;
  }

  lock(): void {
    this.password = null;
    this.payload = EMPTY;
  }

  getSecret(providerId: string): ProviderSecret | null {
    if (!this.unlocked) return null;
    return this.payload.secrets[providerId] ?? null;
  }

  hasSecret(providerId: string): boolean {
    return Boolean(this.payload.secrets[providerId]);
  }

  async setSecret(providerId: string, secret: ProviderSecret): Promise<void> {
    this.requireUnlocked();
    this.payload.secrets[providerId] = secret;
    await this.persist();
  }

  async removeSecret(providerId: string): Promise<void> {
    this.requireUnlocked();
    delete this.payload.secrets[providerId];
    await this.persist();
  }

  /** Portable encrypted backup. Safe to store as a file; still password-protected. */
  exportBackup(): string {
    if (!this.file) throw new VaultError('CORRUPT_VAULT', '没有可导出的保险库。');
    return JSON.stringify(this.file, null, 2);
  }

  async importBackup(json: string, password: string): Promise<void> {
    let parsed: unknown;
    try {
      parsed = JSON.parse(json);
    } catch {
      throw new VaultError('CORRUPT_VAULT', '备份文件不是有效的 JSON。');
    }
    if (!isVaultFile(parsed)) throw new VaultError('CORRUPT_VAULT', '备份文件不是 SOL AI 加密保险库格式。');
    const payload = await decryptVault<VaultPayload>(password, parsed);
    if (!payload || typeof payload.secrets !== 'object') throw new VaultError('CORRUPT_VAULT', '备份内容格式异常。');
    this.file = parsed;
    this.password = password;
    this.payload = payload;
    await this.persist();
  }

  async changePassword(current: string, next: string): Promise<void> {
    if (!this.file) throw new VaultError('CORRUPT_VAULT', '没有可修改的保险库。');
    if (next.length < 8) throw new VaultError('EMPTY_PASSWORD', '新密码至少需要 8 个字符。');
    const rotated = await reencryptVault<VaultPayload>(current, next, this.file);
    this.file = rotated;
    this.password = next;
    await this.persist();
  }

  /** Permanently erase the encrypted blob and all in-memory secrets. */
  async deleteVault(): Promise<void> {
    await idbDelete(STORE_VAULT, VAULT_KEY);
    this.file = null;
    this.password = null;
    this.payload = EMPTY;
  }

  private requireUnlocked(): void {
    if (!this.unlocked || !this.file) throw new VaultError('INVALID_PASSWORD', '保险库已锁定，请先解锁。');
  }

  private async persist(): Promise<void> {
    if (!this.file || !this.password) throw new VaultError('INVALID_PASSWORD', '保险库已锁定。');
    const createdAt = this.file.createdAt;
    const fresh = await encryptVault<VaultPayload>(this.password, this.payload);
    // Fresh salt + IV on every write; keep the original creation timestamp.
    this.file = { ...fresh, createdAt };
    await idbSet(STORE_VAULT, VAULT_KEY, this.file);
  }
}

export const vault = new Vault();
