import { useState } from 'react';
import { useApp } from '../state/AppContext';
import { Button, Callout, Field, InlineStatus, Pill, SectionHead } from '../components/ui';
import { vault } from '../lib/vault';

export function VaultPage(): JSX.Element {
  const { vaultExists, vaultUnlocked, refreshVault, providers } = useApp();
  const [password, setPassword] = useState('');
  const [confirm, setConfirm] = useState('');
  const [currentPw, setCurrentPw] = useState('');
  const [nextPw, setNextPw] = useState('');
  const [importPw, setImportPw] = useState('');
  const [importText, setImportText] = useState('');
  const [busy, setBusy] = useState(false);
  const [status, setStatus] = useState<{ text: string; tone: 'muted' | 'ok' | 'err' | 'warn' }>({ text: '', tone: 'muted' });

  const run = async (fn: () => Promise<void>, ok: string) => {
    setBusy(true);
    setStatus({ text: '', tone: 'muted' });
    try {
      await fn();
      await refreshVault();
      setStatus({ text: ok, tone: 'ok' });
      setPassword('');
      setConfirm('');
      setCurrentPw('');
      setNextPw('');
      setImportPw('');
      setImportText('');
    } catch (e) {
      setStatus({ text: e instanceof Error ? e.message : '操作失败', tone: 'err' });
    } finally {
      setBusy(false);
    }
  };

  const exportBackup = () => {
    const blob = new Blob([vault.exportBackup()], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `sol-ai-backup-${new Date().toISOString().slice(0, 10)}.solai-vault.json`;
    a.click();
    URL.revokeObjectURL(url);
    setStatus({ text: '已导出加密备份。备份本身仍是密文，请同时妥善保管密码。', tone: 'ok' });
  };

  const importFile = async (file: File | undefined) => {
    if (!file) return;
    setImportText(await file.text());
    setStatus({ text: `已读取 ${file.name}，请输入该备份的密码后导入。`, tone: 'muted' });
  };

  return (
    <>
      <div className="page-head">
        <div className="eyebrow">Security / Bring Your Own Key</div>
        <h1 className="page-title display">密钥保险库</h1>
        <p className="page-lede">
          你的 API Key 用浏览器 Web Crypto 加密后只保存在本机。Worker 只在上游请求时代理转发，不持久化、不记录、不落日志。
          重新打开项目后解锁保险库，即可继续用原来的 task_id 查询未完成的生成任务。
        </p>
      </div>

      <Callout>
        <strong>浏览器本地加密不是绝对安全。</strong>
        它能防止明文落盘和随手查看，但无法抵御同源的恶意脚本、被入侵的浏览器扩展或已解锁设备上的本地访问。
        请不要在公共或不受信任的设备上保存密钥；重要 Key 建议设置服务商侧的额度上限并定期轮换。
        未来若提供云端托管密钥，将作为明确的可选功能，采用独立加密密钥、权限隔离、审计与删除机制，绝不默认开启。
      </Callout>

      {/* Create / unlock */}
      {!vaultExists ? (
        <div className="tool-card" style={{ maxWidth: 520 }}>
          <div className="tool-card-tag">Step 01</div>
          <div className="tool-card-title" style={{ fontSize: 20 }}>创建保险库</div>
          <div className="tool-card-desc">设置一个解锁密码。密码不会被保存，忘记密码将无法恢复已保存的密钥（但可以随时删除并重新录入）。</div>
          <div style={{ marginTop: 20 }}>
            <Field label="解锁密码" hint="至少 8 位"><input className="input" type="password" autoComplete="new-password" value={password} onChange={(e) => setPassword(e.target.value)} /></Field>
            <Field label="确认密码"><input className="input" type="password" autoComplete="new-password" value={confirm} onChange={(e) => setConfirm(e.target.value)} /></Field>
            <Button
              variant="primary"
              disabled={busy}
              onClick={() =>
                void run(async () => {
                  if (password !== confirm) throw new Error('两次输入的密码不一致。');
                  await vault.create(password);
                }, '保险库已创建。现在可以添加 Provider 并保存 API Key 了。')
              }
            >
              创建并解锁
            </Button>
          </div>
        </div>
      ) : !vaultUnlocked ? (
        <div className="tool-card" style={{ maxWidth: 520 }}>
          <div className="tool-card-tag">Locked</div>
          <div className="tool-card-title" style={{ fontSize: 20 }}>解锁保险库</div>
          <div className="tool-card-desc">本机已有加密保险库。解锁后密钥仅存在于当前页面的内存中，锁定或刷新即清除。</div>
          <div style={{ marginTop: 20 }}>
            <Field label="解锁密码"><input className="input" type="password" autoComplete="current-password" value={password} onChange={(e) => setPassword(e.target.value)} /></Field>
            <Button variant="primary" disabled={busy} onClick={() => void run(() => vault.unlock(password), '已解锁。')}>解锁</Button>
          </div>
        </div>
      ) : (
        <>
          <SectionHead num="01" title="保险库状态" aside={<Pill tone="ok">UNLOCKED</Pill>} />
          <div className="stat-grid" style={{ marginBottom: 32 }}>
            <div className="stat"><div className="stat-val">{vault.storedProviderIds.length}</div><div className="stat-lbl">已存密钥</div></div>
            <div className="stat"><div className="stat-val">{providers.length}</div><div className="stat-lbl">Provider 配置</div></div>
            <div className="stat"><div className="stat-val mono" style={{ fontSize: 12 }}>AES-256-GCM</div><div className="stat-lbl">加密算法</div></div>
            <div className="stat"><div className="stat-val mono" style={{ fontSize: 12 }}>PBKDF2 310k</div><div className="stat-lbl">密钥派生</div></div>
          </div>

          <SectionHead num="02" title="已保存的密钥" aside="只显示 Provider ID，不显示密钥内容" />
          {vault.storedProviderIds.length === 0 ? (
            <Callout neutral>保险库中还没有密钥。到「我的 AI 模型」编辑 Provider 并填入 API Key 即可。</Callout>
          ) : (
            <div style={{ marginBottom: 32 }}>
              {vault.storedProviderIds.map((id) => {
                const p = providers.find((x) => x.id === id);
                return (
                  <div className="row" key={id}>
                    <div className="row-main">
                      <div className="row-name">{p?.name ?? '(配置已删除)'}</div>
                      <div className="row-meta">{id} · •••••••••••• 加密保存</div>
                    </div>
                    <div className="row-actions">
                      <Button size="sm" variant="danger" onClick={() => void run(() => vault.removeSecret(id), `已删除 ${p?.name ?? id} 的本机密钥。`)}>删除密钥</Button>
                    </div>
                  </div>
                );
              })}
            </div>
          )}

          <SectionHead num="03" title="备份与管理" aside="Export / Import / Rotate / Delete" />
          <div className="grid-2">
            <div className="tool-card" style={{ minHeight: 0 }}>
              <div className="tool-card-tag">Backup</div>
              <div className="tool-card-title" style={{ fontSize: 16, margin: '12px 0 6px' }}>导出加密备份</div>
              <div className="tool-card-desc">下载一个仍是密文的 JSON 文件，可在另一台设备上导入。密码不会包含在文件中。</div>
              <div className="tool-card-foot"><Pill>密文导出</Pill><Button size="sm" onClick={exportBackup}>下载备份</Button></div>
            </div>
            <div className="tool-card" style={{ minHeight: 0 }}>
              <div className="tool-card-tag">Restore</div>
              <div className="tool-card-title" style={{ fontSize: 16, margin: '12px 0 6px' }}>导入备份</div>
              <div className="tool-card-desc">导入会替换本机的保险库内容，请先导出当前备份。</div>
              <div style={{ marginTop: 12, display: 'flex', flexDirection: 'column', gap: 8 }}>
                <input className="input" type="file" accept=".json,.solai-vault.json" onChange={(e) => void importFile(e.target.files?.[0])} />
                <input className="input" type="password" placeholder="该备份的密码" value={importPw} onChange={(e) => setImportPw(e.target.value)} />
                <Button size="sm" disabled={!importText || !importPw || busy} onClick={() => void run(() => vault.importBackup(importText, importPw), '备份已导入。')}>导入</Button>
              </div>
            </div>
            <div className="tool-card" style={{ minHeight: 0 }}>
              <div className="tool-card-tag">Rotate</div>
              <div className="tool-card-title" style={{ fontSize: 16, margin: '12px 0 6px' }}>更换密码</div>
              <div className="tool-card-desc">使用新的随机盐与 IV 重新加密全部内容。</div>
              <div style={{ marginTop: 12, display: 'flex', flexDirection: 'column', gap: 8 }}>
                <input className="input" type="password" placeholder="当前密码" value={currentPw} onChange={(e) => setCurrentPw(e.target.value)} />
                <input className="input" type="password" placeholder="新密码（至少 8 位）" value={nextPw} onChange={(e) => setNextPw(e.target.value)} />
                <Button size="sm" disabled={busy} onClick={() => void run(() => vault.changePassword(currentPw, nextPw), '密码已更换，请牢记新密码。')}>更换密码</Button>
              </div>
            </div>
            <div className="tool-card" style={{ minHeight: 0 }}>
              <div className="tool-card-tag">Danger zone</div>
              <div className="tool-card-title" style={{ fontSize: 16, margin: '12px 0 6px' }}>锁定 / 删除</div>
              <div className="tool-card-desc">锁定会立即清除内存中的明文；删除会永久移除本机加密保险库及所有已存密钥。</div>
              <div className="tool-card-foot">
                <Button size="sm" onClick={() => void run(async () => { vault.lock(); }, '已锁定，内存中的明文密钥已清除。')}>锁定</Button>
                <Button size="sm" variant="danger" onClick={() => { if (window.confirm('确认永久删除本机保险库及全部密钥？此操作不可撤销。')) void run(() => vault.deleteVault(), '保险库与本机密钥已永久删除。'); }}>删除全部</Button>
              </div>
            </div>
          </div>
        </>
      )}

      {status.text ? <InlineStatus text={status.text} tone={status.tone} /> : null}

      <div className="notice">
        实现细节：PBKDF2-SHA256（310,000 次迭代，16 字节随机盐）派生 AES-256-GCM 密钥，每次写入使用新的 12 字节随机 IV。
        明文 Key 不进入 localStorage / sessionStorage / Cookie / 服务器；解锁后的 Key 只在内存中，且仅用于本次上游请求的代理信封。
      </div>
    </>
  );
}
