/**
 * Tiny IndexedDB wrapper. Everything non-secret (provider metadata, guest
 * projects, settings) and the single encrypted vault blob live here.
 * Deliberately no localStorage usage at all.
 */

const DB_NAME = 'sol-ai-local';
const DB_VERSION = 1;
export const STORE_KV = 'kv';
export const STORE_VAULT = 'vault';

let dbPromise: Promise<IDBDatabase> | null = null;

function openDb(): Promise<IDBDatabase> {
  if (dbPromise) return dbPromise;
  dbPromise = new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, DB_VERSION);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(STORE_KV)) db.createObjectStore(STORE_KV);
      if (!db.objectStoreNames.contains(STORE_VAULT)) db.createObjectStore(STORE_VAULT);
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error ?? new Error('IndexedDB open failed'));
  });
  return dbPromise;
}

function tx<T>(store: string, mode: IDBTransactionMode, run: (s: IDBObjectStore) => IDBRequest<T>): Promise<T> {
  return openDb().then(
    (db) =>
      new Promise<T>((resolve, reject) => {
        const transaction = db.transaction(store, mode);
        const request = run(transaction.objectStore(store));
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error ?? new Error('IndexedDB request failed'));
        transaction.onabort = () => reject(transaction.error ?? new Error('IndexedDB transaction aborted'));
      }),
  );
}

export function idbGet<T>(store: string, key: string): Promise<T | undefined> {
  return tx<T | undefined>(store, 'readonly', (s) => s.get(key) as IDBRequest<T | undefined>);
}

export function idbSet<T>(store: string, key: string, value: T): Promise<IDBValidKey> {
  return tx<IDBValidKey>(store, 'readwrite', (s) => s.put(value, key));
}

export function idbDelete(store: string, key: string): Promise<undefined> {
  return tx<undefined>(store, 'readwrite', (s) => s.delete(key) as IDBRequest<undefined>);
}

export function idbKeys(store: string): Promise<IDBValidKey[]> {
  return tx<IDBValidKey[]>(store, 'readonly', (s) => s.getAllKeys());
}

export function idbClear(store: string): Promise<undefined> {
  return tx<undefined>(store, 'readwrite', (s) => s.clear() as IDBRequest<undefined>);
}

export const KV = {
  providers: 'providers',
  projects: 'projects',
  settings: 'settings',
  tasks: 'tasks',
  usage: 'usage',
} as const;

export const VAULT_KEY = 'current';
