/**
 * Cost control.
 *
 * HARD RULE: no price is ever invented. If the provider has no user-entered,
 * sourced price rule, the estimate is explicitly UNKNOWN. Unknown is NOT zero.
 */

import type { BudgetConfig, ProviderConfig } from './types';

export type CostEstimate =
  | { status: 'unknown'; reason: string }
  | { status: 'known'; amount: number; currency: string; basis: string };

export interface CallVolume {
  inputTokens?: number;
  outputTokens?: number;
  requests?: number;
  seconds?: number;
  images?: number;
}

export function estimateCost(config: ProviderConfig, volume: CallVolume): CostEstimate {
  const rule = config.priceRule;
  if (!rule) {
    return {
      status: 'unknown',
      reason: '该服务商未提供可靠计价依据，且尚未在 Provider 中录入价格表。费用标记为未知（不是 0）。请自行在服务商控制台核对账单。',
    };
  }
  let amount = 0;
  switch (rule.unit) {
    case 'per_1k_tokens':
      amount = ((volume.inputTokens ?? 0) / 1000) * (rule.input ?? 0) + ((volume.outputTokens ?? 0) / 1000) * (rule.output ?? 0);
      break;
    case 'per_request':
      amount = (volume.requests ?? 0) * (rule.amount ?? 0);
      break;
    case 'per_second':
      amount = (volume.seconds ?? 0) * (rule.amount ?? 0);
      break;
    case 'per_image':
      amount = (volume.images ?? 0) * (rule.amount ?? 0);
      break;
  }
  return {
    status: 'known',
    amount,
    currency: rule.currency,
    basis: `${rule.unit} · 来源：${rule.source}`,
  };
}

export interface Preflight {
  providerName: string;
  modelId: string;
  volume: CallVolume;
  estimate: CostEstimate;
  budget: BudgetConfig | null;
  currentSpend: number;
  blocked: boolean;
  reasons: string[];
}

/**
 * Everything that must be shown BEFORE each call, per product spec:
 * provider / model / expected volume / estimated cost / current budget / continue.
 */
export function buildPreflight(
  config: ProviderConfig,
  volume: CallVolume,
  budget: BudgetConfig | null,
  currentSpend = 0,
): Preflight {
  const reasons: string[] = [];
  const estimate = estimateCost(config, volume);
  if (budget?.paused) reasons.push('项目任务已暂停。');
  if (estimate.status === 'unknown') reasons.push('费用未知，无法自动判断是否超出预算。');
  if (budget?.projectLimit !== null && budget?.projectLimit !== undefined) {
    if (currentSpend >= budget.projectLimit) reasons.push(`已达到单项目预算上限 ${budget.projectLimit} ${budget.currency}。`);
    if (estimate.status === 'known' && currentSpend + estimate.amount > budget.projectLimit) {
      reasons.push(`本次调用预计会使累计费用超过单项目预算上限。`);
    }
  }
  if (budget?.perShotLimit !== null && budget?.perShotLimit !== undefined && estimate.status === 'known') {
    if (estimate.amount > budget.perShotLimit) reasons.push(`本次调用预计费用超过单镜头预算 ${budget.perShotLimit} ${budget.currency}。`);
  }
  return {
    providerName: config.name,
    modelId: config.modelId || '(未填写)',
    volume,
    estimate,
    budget,
    currentSpend,
    blocked: reasons.some((r) => r.includes('上限') || r.includes('暂停')),
    reasons,
  };
}

export function defaultBudget(): BudgetConfig {
  return {
    projectLimit: null,
    perShotLimit: null,
    currency: 'CNY',
    maxConcurrentTasks: 1,
    maxRetries: 1,
    paused: false,
    spentConfirmed: 0,
  };
}

export function formatEstimate(estimate: CostEstimate): string {
  return estimate.status === 'unknown' ? '未知（无可靠计价依据）' : `${estimate.amount.toFixed(4)} ${estimate.currency}`;
}
