import { useApp, type Route } from '../state/AppContext';

const NAV: Array<{ id: Route; label: string }> = [
  { id: 'home', label: '工作台' },
  { id: 'projects', label: '项目' },
  { id: 'studio', label: 'Studio' },
  { id: 'providers', label: '模型' },
  { id: 'assets', label: '素材' },
  { id: 'vault', label: '保险库' },
  { id: 'settings', label: '设置' },
];

export function Shell({ children }: { children: React.ReactNode }): JSX.Element {
  const { route, navigate, vaultExists, vaultUnlocked, refreshVault, theme, setTheme, apiOnline, runtime } = useApp();
  const modeLabel = apiOnline ? '云端已连接' : runtime.callMode === 'direct' ? '直连模式' : '本机模式';

  return (
    <div className="shell">
      <header className="topbar">
        <div className="topbar-inner">
          <button className="brand" onClick={() => navigate('home')} aria-label="SOL AI 工作台">
            <span className="brand-wordmark">SOL AI</span>
            <span className="brand-dot" aria-hidden="true" />
          </button>

          <nav className="topnav" aria-label="主导航">
            {NAV.map((item) => (
              <button
                key={item.id}
                className={`topnav-item ${route === item.id ? 'active' : ''}`}
                aria-current={route === item.id ? 'page' : undefined}
                onClick={() => navigate(item.id)}
              >
                {item.label}
              </button>
            ))}
          </nav>

          <div className="topmeta">
            <button
              className="topmeta-status"
              onClick={async () => {
                await refreshVault();
                navigate('vault');
              }}
              title="查看密钥保险库"
            >
              <span className={`topmeta-dot ${vaultUnlocked ? 'on' : vaultExists ? 'warn' : ''}`} />
              {vaultUnlocked ? '已解锁' : vaultExists ? '已锁定' : '本地模式'}
            </button>
            <button
              className="text-btn"
              onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')}
              aria-label={theme === 'light' ? '切换到深色模式' : '切换到浅色模式'}
            >
              {theme === 'light' ? '深色' : '浅色'}
            </button>
          </div>
        </div>
      </header>

      <main className={`content ${route === 'home' ? 'content-home' : ''}`}>{children}</main>

      <footer className="site-foot">
        <span>SOL AI · SolYoung AI Studio</span>
        <span>{modeLabel} · 自带 API Key，平台不代付模型费用</span>
      </footer>
    </div>
  );
}
