import { useState } from 'react';
import { useApp } from '../state/AppContext';
import { capabilityLabel, protocolLabel } from '../lib/providers';

export function Home(): JSX.Element {
  const { navigate, providers, projects, newProject, openProject, vaultExists, vaultUnlocked, apiOnline } = useApp();
  const [draft, setDraft] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');

  const textModels = providers.filter((p) => p.enabled && p.capabilities.includes('text'));

  /** Composer really creates a local project and carries the script into the Studio. */
  const start = async (blank = false) => {
    if (busy) return;
    setBusy(true);
    setError('');
    try {
      const script = blank ? '' : draft;
      const firstLine = script.trim().split('\n').map((l) => l.trim()).find(Boolean) ?? '';
      const title = firstLine ? (firstLine.length > 20 ? `${firstLine.slice(0, 20)}…` : firstLine) : '未命名项目';
      const project = await newProject(title, script);
      if (!blank) setDraft('');
      openProject(project.id);
    } catch (e) {
      setError(e instanceof Error ? e.message : '创建项目失败');
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="home">
      <section className="home-hero">
        <div className="home-kicker">SolYoung AI Studio</div>
        <h1 className="home-title display">SOL AI</h1>
        <p className="home-sub">一个工作空间，连接你自己的 AI 模型，完成你的创作。</p>
        <p className="home-sub-en">One workspace. Your models. Your creativity.</p>
      </section>

      <div className="composer">
        <textarea
          className="composer-input"
          rows={4}
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) void start(false);
          }}
          placeholder="粘贴口播文稿，或写下你想做的视频…"
          aria-label="口播文稿或创作描述"
        />
        <div className="composer-bar">
          <span className="composer-meta">
            {textModels.length > 0 ? `${textModels.length} 个文本模型可用` : '尚未配置文本模型'}
            {' · '}保险库{vaultUnlocked ? '已解锁' : vaultExists ? '已锁定' : '未创建'}
          </span>
          <div className="composer-actions">
            <button className="text-btn" onClick={() => navigate('providers')}>配置模型</button>
            <button className="composer-send" onClick={() => void start(false)} disabled={busy} aria-label="开始创作" title="开始创作（⌘/Ctrl + Enter）">
              <svg viewBox="0 0 20 20" fill="none" aria-hidden="true">
                <path d="M10 15.5V5M10 5 5.8 9.2M10 5l4.2 4.2" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" />
              </svg>
            </button>
          </div>
        </div>
      </div>

      <div className="home-links">
        <button className="home-link" onClick={() => void start(true)} disabled={busy}>新建空白项目</button>
        <button className="home-link" onClick={() => navigate('studio')}>AI Video Studio</button>
        <button className="home-link" onClick={() => navigate('providers')}>配置我的 AI 模型</button>
        <button className="home-link" onClick={() => navigate('vault')}>密钥保险库</button>
        <button className="home-link" onClick={() => navigate('settings')}>设置</button>
      </div>

      <div className="home-status">
        本机数据 · {projects.length} 个项目 · {providers.length} 个模型 · {apiOnline ? '云端已连接' : '云端未连接'}
      </div>
      {error ? <div className="home-error">{error}</div> : null}

      {/* 最近项目 */}
      <section className="home-block">
        <div className="home-block-head">
          <h2 className="home-block-title">最近项目</h2>
          <button className="home-block-more" onClick={() => navigate('projects')}>全部 →</button>
        </div>
        {projects.length === 0 ? (
          <p className="home-empty">还没有项目。在上面的输入框写下口播文稿，就会创建一个项目并进入 AI Video Studio。</p>
        ) : (
          projects.slice(0, 4).map((p) => (
            <div className="home-row" key={p.id}>
              <div className="home-row-main">
                <div className="home-row-name">{p.title}</div>
                <div className="home-row-meta">{p.id} · {new Date(p.updatedAt).toLocaleString('zh-CN')} · {p.script.length} 字符文稿</div>
              </div>
              <button className="home-row-action" onClick={() => openProject(p.id)}>打开 →</button>
            </div>
          ))
        )}
      </section>

      {/* 我的 AI 模型 */}
      <section className="home-block">
        <div className="home-block-head">
          <h2 className="home-block-title">我的 AI 模型</h2>
          <button className="home-block-more" onClick={() => navigate('providers')}>管理 →</button>
        </div>
        {providers.length === 0 ? (
          <p className="home-empty">尚未配置模型。SOL AI 不内置任何人的 Key，也不替其他用户付费；添加你自己的接口后才能发起真实调用。</p>
        ) : (
          providers.slice(0, 4).map((p) => (
            <div className="home-row" key={p.id}>
              <div className="home-row-main">
                <div className="home-row-name">
                  {p.name}
                  {p.lastTest?.code === 'CONNECTION_OK' ? <span className="faint" style={{ fontSize: 11, fontWeight: 400 }}>已验证</span> : null}
                </div>
                <div className="home-row-meta">
                  {p.baseUrl || '(未填写 Base URL)'} · {p.modelId || '(未填写 Model ID)'} · {protocolLabel(p.protocol)} · {p.capabilities.map(capabilityLabel).join(' / ') || '无能力标注'}
                </div>
              </div>
              <button className="home-row-action" onClick={() => navigate('providers')}>编辑 →</button>
            </div>
          ))
        )}
      </section>

      {/* 我的创作工具 */}
      <section className="home-block">
        <div className="home-block-head">
          <h2 className="home-block-title">我的创作工具</h2>
          <span className="home-block-more">1 个可用 · 其余规划中</span>
        </div>
        <div className="home-row">
          <div className="home-row-main">
            <div className="home-row-name">AI VIDEO STUDIO</div>
            <div className="home-row-meta">文稿 → 分镜 JSON → 成片工作流。当前可用：项目、原始文稿、分镜 Schema、成本预检与真实文本模型调用。</div>
          </div>
          <button className="home-row-action" onClick={() => navigate('studio')}>打开 →</button>
        </div>
        <div className="home-row">
          <div className="home-row-main">
            <div className="home-row-name" style={{ color: 'var(--ink-faint)' }}>可扩展的应用层</div>
            <div className="home-row-meta">AI 图片 / 语音 / 脚本 / 分镜 / 创意工作流 · 尚未实现，不做假入口</div>
          </div>
          <span className="home-row-action">未实现</span>
        </div>
      </section>

      {/* 素材资产 */}
      <section className="home-block">
        <div className="home-block-head">
          <h2 className="home-block-title">素材资产</h2>
          <button className="home-block-more" onClick={() => navigate('assets')}>查看 →</button>
        </div>
        <p className="home-empty">
          {apiOnline ? '素材库为空。' : '云端未连接，素材库当前不可用。'}
          {' '}视频、图片、音频与字幕会按 workspace 前缀隔离存放；目前没有任何示例文件或伪造状态。
        </p>
      </section>

      {/* 设置 */}
      <section className="home-block">
        <div className="home-block-head"><h2 className="home-block-title">设置</h2></div>
        <div className="home-links" style={{ justifyContent: 'flex-start', marginTop: 12, gap: 24 }}>
          <button className="home-link" onClick={() => navigate('vault')}>密钥与安全</button>
          <button className="home-link" onClick={() => navigate('providers')}>模型与接口</button>
          <button className="home-link" onClick={() => navigate('settings')}>工作空间与环境</button>
          <button className="home-link" onClick={() => navigate('studio')}>成本与预算</button>
        </div>
      </section>

      <div className="home-foot">
        SOL AI 是支持自带 API Key 的创作工作平台，不是某个模型的调用页面。浏览器本地加密不等于绝对安全；完整说明见仓库 docs/SECURITY.md 与 docs/ROADMAP.md。
      </div>
    </div>
  );
}
