export function emptyProvider(partial: Partial<ProviderConfig> = {}): ProviderConfig {
  const now = new Date().toISOString();
  return {
    id: newId('prv_'),
    name: '',
    baseUrl: '',
    modelId: '',
    protocol: 'openai-compatible',
    functionalType: 'text',
    capabilities: [],
    endpoints: {},
    requestParams: {},
    timeoutMs: 60_000,
    enabled: true,
    createdAt: now,
    updatedAt: now,
    lastTest: null,
    ...partial,
  };
}

export interface ProviderPreset {
  id: string;
  label: string;
  description: string;
  /** false = the upstream contract has NOT been verified; fields stay blank. */
  verified: boolean;
  warning?: string;
  config: Partial<ProviderConfig>;
}

