export function capabilityLabel(id: Capability): string {
  return CAPABILITIES.find((c) => c.id === id)?.label ?? id;
}

export function protocolLabel(id: ProviderProtocol): string {
  return PROTOCOLS.find((p) => p.id === id)?.label ?? id;
}

/** Deliberately absent: no function that guesses capabilities from a model name. */
