/**
 * Provider Adapter layer.
 *
 * - Each protocol has its own request builder. No "one shape fits all".
 * - "Test connection" ALWAYS sends a real upstream request (never just checks
 *   that the key string is non-empty).
 * - Error classification maps upstream signals to explicit, honest outcomes.
 * - Secrets are stripped from anything we display or log.
 */

import type { ProviderConfig, ProxyEnvelope, ProxyResponse, TestResult, TestOutcomeCode } from './types';

export const OUTCOME_LABELS: Record<TestOutcomeCode, string> = {
  CONNECTION_OK: '连接成功',
  INVALID_KEY: 'Key 无效',
  MODEL_NOT_FOUND: '模型不存在',
  PERMISSION_DENIED: '权限不足',
  INCOMPATIBLE: '接口不兼容',
  INSUFFICIENT_BALANCE: '余额不足',
  RATE_LIMITED: '请求过于频繁',
  TIMEOUT: '请求超时',
  NETWORK_ERROR: '网络错误',
  UNKNOWN_ERROR: '其他错误',
  NOT_TESTABLE: '未执行测试',
};

export type TestPlan =
  | { kind: 'http'; envelope: ProxyEnvelope; note: string }
  | { kind: 'not-testable'; reason: string };

export function joinUrl(baseUrl: string, path?: string): string {
  if (!path) return baseUrl.replace(/\/+$/, '');
  if (/^https?:\/\//i.test(path)) return path;
  return `${baseUrl.replace(/\/+$/, '')}/${path.replace(/^\/+/, '')}`;
}

function jsonHeaders(apiKey: string, extra?: Record<string, string>): Record<string, string> {
  return { 'content-type': 'application/json', authorization: `Bearer ${apiKey}`, ...extra };
}

function minimalChatBody(modelId: string, params: Record<string, unknown>): string {
  return JSON.stringify({
    model: modelId,
    messages: [{ role: 'user', content: 'Reply with exactly: OK' }],
    max_tokens: 8,
    stream: false,
    ...params,
  });
}

/**
 * Build a real, low-cost upstream test request.
 *
 * For text protocols a genuine chat completion is used because it validates
 * key validity, model existence, permission and quota in one real call.
 * For generation protocols there is often NO side-effect-free endpoint, so we
 * refuse to invent one: the user must configure `endpoints.test` or explicitly
 * authorise a real (billable) generation probe.
 */
export function buildTestPlan(config: ProviderConfig, apiKey: string, opts: { allowBillableProbe?: boolean } = {}): TestPlan {
  if (!apiKey) return { kind: 'not-testable', reason: '未解锁保险库，无法取得该 Provider 的 API Key。' };
  if (!config.baseUrl) return { kind: 'not-testable', reason: '尚未填写 API Base URL。' };

  const timeoutMs = Math.min(config.timeoutMs || 60_000, 120_000);

  switch (config.protocol) {
    case 'openai-compatible': {
      if (!config.modelId) return { kind: 'not-testable', reason: '尚未填写 Model ID，无法验证模型是否真实存在。' };
      return {
        kind: 'http',
        note: '向上游发送一次真实的 chat completion（max_tokens=8），用于同时验证 Key、模型 ID、权限与额度。会产生极小的真实调用费用。',
        envelope: {
          url: joinUrl(config.baseUrl, config.endpoints.chat ?? '/chat/completions'),
          method: 'POST',
          headers: jsonHeaders(apiKey),
          body: minimalChatBody(config.modelId, config.requestParams),
          timeoutMs,
        },
      };
    }
    case 'anthropic': {
      if (!config.modelId) return { kind: 'not-testable', reason: '尚未填写 Model ID，无法验证模型是否真实存在。' };
      return {
        kind: 'http',
        note: '向 Anthropic Messages API 发送一次真实请求（max_tokens=8）。会产生极小的真实调用费用。',
        envelope: {
          url: joinUrl(config.baseUrl, config.endpoints.chat ?? '/messages'),
          method: 'POST',
          headers: { 'content-type': 'application/json', 'x-api-key': apiKey, 'anthropic-version': '2023-06-01' },
          body: JSON.stringify({
            model: config.modelId,
            max_tokens: 8,
            messages: [{ role: 'user', content: 'Reply with exactly: OK' }],
            ...config.requestParams,
          }),
          timeoutMs,
        },
      };
    }
    case 'custom-http': {
      const path = config.endpoints.test ?? config.endpoints.chat;
      if (!path) {
        return {
          kind: 'not-testable',
          reason: '自定义 HTTP 协议没有可推断的测试端点。请在「测试端点」中显式填写一个无副作用的健康检查地址，或填写 chat 端点并提供请求参数模板。',
        };
      }
      const isTestOnly = Boolean(config.endpoints.test);
      return {
        kind: 'http',
        note: isTestOnly
          ? '调用你显式配置的测试端点。'
          : '调用你配置的 chat 端点，请求体由「请求参数」模板与 Model ID 组成。请确认该端点不会触发计费任务。',
        envelope: {
          url: joinUrl(config.baseUrl, path),
          method: isTestOnly ? 'GET' : 'POST',
          headers: jsonHeaders(apiKey),
          ...(isTestOnly ? {} : { body: JSON.stringify({ model: config.modelId, ...config.requestParams }) }),
          timeoutMs,
        },
      };
    }
    case 'image-generation':
    case 'video-generation':
    case 'tts':
    case 'voice-cloning': {
      if (config.endpoints.test) {
        return {
          kind: 'http',
          note: '调用你显式配置的无副作用测试端点。',
          envelope: {
            url: joinUrl(config.baseUrl, config.endpoints.test),
            method: 'GET',
            headers: jsonHeaders(apiKey),
            timeoutMs,
          },
        };
      }
      if (opts.allowBillableProbe) {
        const template = config.requestParams.createBodyTemplate;
        const createPath = config.endpoints.videoCreate ?? config.endpoints.image ?? config.endpoints.tts;
        if (createPath && template && typeof template === 'object') {
          return {
            kind: 'http',
            note: '按你提供的请求体模板发送一次真实生成请求。此调用会产生上游费用，且不会把 HTTP 202 当作任务完成。',
            envelope: {
              url: joinUrl(config.baseUrl, createPath),
              method: 'POST',
              headers: jsonHeaders(apiKey),
              body: JSON.stringify({ model: config.modelId, ...(template as Record<string, unknown>) }),
              timeoutMs,
            },
          };
        }
      }
      return {
        kind: 'not-testable',
        reason:
          '该协议没有可推断的无副作用测试端点。SOL AI 不会猜测生成接口。请配置「测试端点」，或在「请求参数」中提供 createBodyTemplate 并显式授权一次真实（可能计费的）生成探测。',
      };
    }
    default:
      return { kind: 'not-testable', reason: '未知协议，未执行任何请求。' };
  }
}

/** Generic builder for real workflow calls (generation, script, storyboard…). */
export function buildRequest(
  config: ProviderConfig,
  apiKey: string,
  params: { path: string; method?: ProxyEnvelope['method']; body?: unknown; extraHeaders?: Record<string, string> },
): ProxyEnvelope {
  const headers =
    config.protocol === 'anthropic'
      ? { 'content-type': 'application/json', 'x-api-key': apiKey, 'anthropic-version': '2023-06-01', ...params.extraHeaders }
      : jsonHeaders(apiKey, params.extraHeaders);
  return {
    url: joinUrl(config.baseUrl, params.path),
    method: params.method ?? 'POST',
    headers,
    ...(params.body === undefined ? {} : { body: typeof params.body === 'string' ? params.body : JSON.stringify(params.body) }),
    timeoutMs: Math.min(config.timeoutMs || 60_000, 120_000),
  };
}

const MODEL_HINT = /(model|模型).{0,40}(not\s*found|does\s*not\s*exist|unknown|invalid|unavailable|不存在|不可用)/i;
const MODEL_HINT_2 = /(not\s*found|does\s*not\s*exist|unknown|invalid).{0,30}(model|模型)/i;
const QUOTA_HINT = /(insufficient|quota|balance|credit|billing|余额|额度|欠费|arrears|exceeded.*budget)/i;
const AUTH_HINT = /(invalid.*api.?key|incorrect.*api.?key|unauthori[sz]ed|authentication|bad.*credential|invalid.*token)/i;
const INCOMPAT_HINT = /(unsupported|not\s*supported|unknown\s*path|no\s*such\s*endpoint|invalid\s*request|missing\s*required|content.?type|405|501|incompatible|不兼容|不支持)/i;

/** Pure classifier — unit tested. `body` must already be redacted. */
export function classifyResponse(
  status: number,
  body: string,
  transportError?: string,
): Pick<TestResult, 'code' | 'label' | 'detail' | 'httpStatus'> {
  const finish = (code: TestOutcomeCode, detail: string): Pick<TestResult, 'code' | 'label' | 'detail' | 'httpStatus'> => ({
    code,
    label: OUTCOME_LABELS[code],
    detail,
    httpStatus: status || undefined,
  });

  if (transportError) {
    const t = transportError.toLowerCase();
    if (t.includes('timeout') || t.includes('abort')) return finish('TIMEOUT', '上游在超时时间内未响应。请勿直接重试创建任务，先查询原任务状态，避免重复扣费。');
    return finish('NETWORK_ERROR', '无法连接到上游服务：网络不可达、DNS 失败或被拦截。');
  }

  const excerpt = body.slice(0, 400);

  if (status >= 200 && status < 300) {
    // Some gateways return HTTP 200 with an error envelope. Never call that a success.
    try {
      const parsed: unknown = JSON.parse(body);
      if (parsed && typeof parsed === 'object' && 'error' in (parsed as Record<string, unknown>)) {
        return finish('UNKNOWN_ERROR', `上游返回 200，但响应体包含 error 字段：${excerpt}`);
      }
    } catch {
      /* non-JSON success (e.g. plain "OK") is fine */
    }
    return finish('CONNECTION_OK', '上游返回成功响应。Key、模型 ID、权限与该接口格式均已通过真实请求验证。');
  }

  if (status === 401) return finish('INVALID_KEY', '上游拒绝了鉴权信息。请检查 API Key 是否正确、是否过期、以及鉴权头格式。');
  if (status === 402) return finish('INSUFFICIENT_BALANCE', '上游返回需付费 / 余额不足。');
  if (status === 403) {
    if (QUOTA_HINT.test(body)) return finish('INSUFFICIENT_BALANCE', '上游提示额度或余额不足。');
    if (AUTH_HINT.test(body)) return finish('INVALID_KEY', '上游提示鉴权信息无效。');
    return finish('PERMISSION_DENIED', 'Key 有效，但当前账号无权访问该模型或该接口。');
  }
  if (status === 404) {
    return MODEL_HINT.test(body) || MODEL_HINT_2.test(body)
      ? finish('MODEL_NOT_FOUND', '上游明确表示该模型不存在或不可用。请核实 Model ID。')
      : finish('INCOMPATIBLE', '端点不存在（HTTP 404）。该服务商可能不完全兼容此接口协议，请核对 API Base URL 与端点路径。');
  }
  if (status === 400) {
    if (MODEL_HINT.test(body) || MODEL_HINT_2.test(body)) return finish('MODEL_NOT_FOUND', '上游提示模型 ID 无效或不存在。');
    if (QUOTA_HINT.test(body)) return finish('INSUFFICIENT_BALANCE', '上游提示额度不足。');
    return finish('INCOMPATIBLE', '请求格式被上游拒绝（HTTP 400）。请核对协议、请求参数与必填字段。');
  }
  if (status === 405 || status === 415 || status === 422 || status === 501) {
    return finish('INCOMPATIBLE', `上游不支持该请求方法或格式（HTTP ${status}）。请改用匹配的协议适配器。`);
  }
  if (status === 429) return finish('RATE_LIMITED', '上游限流。请稍后再试，不要立即重复创建任务。');
  if (status >= 500) return finish('UNKNOWN_ERROR', `上游服务错误（HTTP ${status}）。${excerpt}`);

  if (QUOTA_HINT.test(body)) return finish('INSUFFICIENT_BALANCE', '响应中提示额度 / 余额问题。');
  if (AUTH_HINT.test(body)) return finish('INVALID_KEY', '响应中提示鉴权信息无效。');
  if (INCOMPAT_HINT.test(body)) return finish('INCOMPATIBLE', '响应中提示接口不兼容。');
  return finish('UNKNOWN_ERROR', `未归类的上游响应（HTTP ${status}）：${excerpt || '(空响应体)'}`);
}

/** Remove secrets from any string before display, logging or persistence. */
export function redactSecrets(text: string, secrets: string[] = []): string {
  let out = text;
  for (const secret of secrets) {
    if (secret && secret.length >= 4) out = out.split(secret).join('[REDACTED]');
  }
  return out
    .replace(/Bearer\s+[A-Za-z0-9._~+/=-]{8,}/gi, 'Bearer [REDACTED]')
    .replace(/(x-api-key\s*[:=]\s*)\S+/gi, '$1[REDACTED]')
    .replace(/("?(?:api[_-]?key|authorization|access[_-]?token|secret|password)"?\s*[:=]\s*)"[^"]*"/gi, '$1"[REDACTED]"')
    .replace(/\bsk-[A-Za-z0-9_-]{12,}/g, '[REDACTED]');
}

/** Compose a fully-classified result from the Worker's sanitized response. */
export function toTestResult(response: ProxyResponse, note: string, testedAt = new Date().toISOString()): TestResult {
  const classified = classifyResponse(response.status, response.body, response.transportError);
  return {
    ...classified,
    detail: response.ok ? `${classified.detail}\n${note}` : classified.detail,
    latencyMs: response.elapsedMs,
    testedAt,
    realUpstreamCall: response.status > 0,
  };
}
