/**
 * Storyboard contract. AI output MUST pass schema validation — a wall of
 * unparseable prose is rejected, never stored as if it were a storyboard.
 *
 * The original script is a first-class field and is preserved verbatim.
 */

export const SHOT_FIELDS = [
  'shot_id',
  'sequence',
  'narration_text',
  'estimated_duration',
  'scene_description',
  'visual_prompt',
  'negative_prompt',
  'camera_movement',
  'shot_type',
  'visual_style',
  'character_description',
  'reference_assets',
  'video_provider',
  'video_model',
  'video_status',
  'generated_asset',
  'transition',
  'subtitle_text',
] as const;

export type ShotField = (typeof SHOT_FIELDS)[number];

export type VideoStatus = 'not_started' | 'queued' | 'creating' | 'processing' | 'succeeded' | 'failed' | 'downloaded';

export interface StoryboardShot {
  shot_id: string;
  sequence: number;
  narration_text: string;
  estimated_duration: number;
  scene_description: string;
  visual_prompt: string;
  negative_prompt: string;
  camera_movement: string;
  shot_type: string;
  visual_style: string;
  character_description: string;
  reference_assets: string[];
  video_provider: string | null;
  video_model: string | null;
  video_status: VideoStatus;
  generated_asset: string | null;
  transition: string;
  subtitle_text: string;
}

export interface Storyboard {
  version: 1;
  project_id: string;
  /** Verbatim user input. Never rewritten or shortened by the model. */
  original_script: string;
  shots: StoryboardShot[];
  generated_at: string;
}

export const VIDEO_STATUSES: VideoStatus[] = [
  'not_started', 'queued', 'creating', 'processing', 'succeeded', 'failed', 'downloaded',
];

/** Portable JSON Schema (also written into exported project bundles). */
export const STORYBOARD_JSON_SCHEMA = {
  $schema: 'https://json-schema.org/draft/2020-12/schema',
  title: 'SOL AI Storyboard',
  type: 'object',
  required: ['version', 'project_id', 'original_script', 'shots', 'generated_at'],
  additionalProperties: false,
  properties: {
    version: { const: 1 },
    project_id: { type: 'string', minLength: 1 },
    original_script: { type: 'string' },
    generated_at: { type: 'string' },
    shots: {
      type: 'array',
      items: {
        type: 'object',
        required: [...SHOT_FIELDS],
        additionalProperties: false,
        properties: Object.fromEntries(
          SHOT_FIELDS.map((field) => {
            if (field === 'sequence' || field === 'estimated_duration') return [field, { type: 'number' }];
            if (field === 'reference_assets') return [field, { type: 'array', items: { type: 'string' } }];
            if (field === 'video_provider' || field === 'video_model' || field === 'generated_asset') {
              return [field, { type: ['string', 'null'] }];
            }
            if (field === 'video_status') return [field, { enum: VIDEO_STATUSES }];
            return [field, { type: 'string' }];
          }),
        ),
      },
    },
  },
} as const;

export interface ValidationResult {
  valid: boolean;
  errors: string[];
  storyboard: Storyboard | null;
}

function isRecord(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

/** Hand-rolled validator: no runtime dependency, strict about field presence. */
export function validateStoryboard(value: unknown): ValidationResult {
  const errors: string[] = [];
  if (!isRecord(value)) return { valid: false, errors: ['分镜结果必须是 JSON 对象。'], storyboard: null };

  if (value.version !== 1) errors.push('version 必须为 1。');
  if (typeof value.project_id !== 'string' || !value.project_id) errors.push('project_id 缺失或类型错误。');
  if (typeof value.original_script !== 'string') errors.push('original_script 必须是字符串（原始文稿不可丢失）。');
  if (typeof value.generated_at !== 'string') errors.push('generated_at 缺失或类型错误。');
  if (!Array.isArray(value.shots)) {
    errors.push('shots 必须是数组。');
  } else {
    if (value.shots.length === 0) errors.push('shots 不能为空。');
    value.shots.forEach((raw, index) => {
      const at = `shots[${index}]`;
      if (!isRecord(raw)) {
        errors.push(`${at} 必须是对象。`);
        return;
      }
      for (const field of SHOT_FIELDS) {
        if (!(field in raw)) errors.push(`${at}.${field} 缺失。`);
      }
      for (const field of SHOT_FIELDS) {
        const v = raw[field];
        if (v === undefined) continue;
        if (field === 'sequence' || field === 'estimated_duration') {
          if (typeof v !== 'number' || !Number.isFinite(v)) errors.push(`${at}.${field} 必须是有限数字。`);
          if (field === 'estimated_duration' && typeof v === 'number' && v <= 0) errors.push(`${at}.estimated_duration 必须大于 0。`);
        } else if (field === 'reference_assets') {
          if (!Array.isArray(v) || !v.every((x) => typeof x === 'string')) errors.push(`${at}.reference_assets 必须是字符串数组。`);
        } else if (field === 'video_provider' || field === 'video_model' || field === 'generated_asset') {
          if (v !== null && typeof v !== 'string') errors.push(`${at}.${field} 必须是字符串或 null。`);
        } else if (field === 'video_status') {
          if (typeof v !== 'string' || !VIDEO_STATUSES.includes(v as VideoStatus)) errors.push(`${at}.video_status 取值非法。`);
        } else if (typeof v !== 'string') {
          errors.push(`${at}.${field} 必须是字符串。`);
        }
      }
      if (typeof raw.sequence === 'number' && raw.sequence !== index + 1) {
        errors.push(`${at}.sequence 应为 ${index + 1}，实际为 ${raw.sequence}（镜头顺序必须连续）。`);
      }
    });
  }

  return errors.length > 0
    ? { valid: false, errors, storyboard: null }
    : { valid: true, errors: [], storyboard: value as unknown as Storyboard };
}

/**
 * Guard against a model silently deleting the user's口播内容.
 * Every non-empty original line (whitespace-normalised) must still appear in
 * the concatenated narration_text. AI may suggest edits, but never erase.
 */
export function preservesOriginalScript(original: string, shots: Pick<StoryboardShot, 'narration_text'>[]): {
  preserved: boolean;
  missing: string[];
} {
  const norm = (s: string): string => s.replace(/\s+/g, '').replace(/[，。！？、,.!?;；:："""''\s]/g, '');
  const narration = norm(shots.map((s) => s.narration_text).join(''));
  const lines = original
    .split(/\r?\n/)
    .map((l) => l.trim())
    .filter((l) => l.length > 0);
  const missing = lines.filter((line) => !narration.includes(norm(line)));
  return { preserved: missing.length === 0, missing };
}

/** Extract a JSON object from a model response that may contain markdown fences. */
export function parseStoryboardResponse(text: string): unknown {
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = (fenced?.[1] ?? text).trim();
  const start = candidate.indexOf('{');
  const end = candidate.lastIndexOf('}');
  if (start === -1 || end <= start) return null;
  try {
    return JSON.parse(candidate.slice(start, end + 1)) as unknown;
  } catch {
    return null;
  }
}
