/**
 * Runtime connection settings for the SOL AI frontend.
 *
 * The app is deployed as a STATIC site (GitHub Pages) at ai.solyoung.top.
 * A static host cannot run the Cloudflare Worker, so the Worker's address and
 * the upstream call strategy must be configurable at runtime instead of being
 * hard-coded to the same origin.
 *
 * This file stores NON-SECRET preferences only. API keys live exclusively in
 * the encrypted vault (IndexedDB) and are never written here.
 */

export type CallMode = 'auto' | 'worker' | 'direct';

export interface RuntimeConfig {
  /** '' = same-origin /api. Otherwise an absolute https:// Worker origin. */
  apiBase: string;
  /**
   * auto   — use the Worker when reachable; otherwise fall back to a direct
   *          browser->upstream request (CORS permitting).
   * worker — Worker only. Never send a key except through the proxy.
   * direct — browser->upstream only. No proxy involved.
   */
  callMode: CallMode;
}

const STORAGE_KEY = 'sol-ai:runtime';
export const RUNTIME_CHANGE_EVENT = 'sol-ai:runtime-change';

export const DEFAULT_RUNTIME: RuntimeConfig = { apiBase: '', callMode: 'auto' };

/** Reject anything that is not a plain http(s) origin — no credentials, paths or JS URLs. */
export function normalizeApiBase(input: string): string {
  const value = input.trim();
  if (!value) return '';
  try {
    const url = new URL(value);
    if (url.protocol !== 'https:' && !(url.protocol === 'http:' && /^(localhost|127\.0\.0\.1)$/.test(url.hostname))) {
      throw new Error('only https is allowed');
    }
    if (url.username || url.password || url.search || url.hash) throw new Error('credentials / query are not allowed');
    if (url.pathname !== '/' && url.pathname !== '') throw new Error('path is not allowed');
    return url.origin;
  } catch {
    throw new Error('API 服务地址必须是一个 https:// 开头的源（例如 https://sol-ai.xxx.workers.dev），或留空使用本站同源。');
  }
}

export function getRuntimeConfig(): RuntimeConfig {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return { ...DEFAULT_RUNTIME };
    const parsed = JSON.parse(raw) as Partial<RuntimeConfig>;
    return {
      apiBase: typeof parsed.apiBase === 'string' ? parsed.apiBase : '',
      callMode: parsed.callMode === 'worker' || parsed.callMode === 'direct' ? parsed.callMode : 'auto',
    };
  } catch {
    return { ...DEFAULT_RUNTIME };
  }
}

export function setRuntimeConfig(next: RuntimeConfig): void {
  const clean: RuntimeConfig = { apiBase: normalizeApiBase(next.apiBase), callMode: next.callMode };
  localStorage.setItem(STORAGE_KEY, JSON.stringify(clean));
  window.dispatchEvent(new Event(RUNTIME_CHANGE_EVENT));
}

/** Build the URL for a Worker API route, honouring a configured external Worker. */
export function apiUrl(path: string): string {
  const base = getRuntimeConfig().apiBase.replace(/\/+$/, '');
  const suffix = path.startsWith('/') ? path : `/${path}`;
  return base ? `${base}/api${suffix}` : `/api${suffix}`;
}

export const CALL_MODE_LABELS: Record<CallMode, string> = {
  auto: '自动（优先 Worker，不可达时直连）',
  worker: '仅 Worker 代理',
  direct: '仅浏览器直连',
};
