import { useEffect, useState } from 'react';
import { useApp } from '../state/AppContext';
import { Button, Callout, Empty, Pill, SectionHead } from '../components/ui';
import { apiFetch } from '../lib/apiClient';

interface AssetRow {
  id: string;
  project_id: string | null;
  kind: string;
  r2_key: string;
  byte_size: number;
  mime_type: string | null;
  created_at: string;
}

export function Assets(): JSX.Element {
  const { apiOnline, me } = useApp();
  const [items, setItems] = useState<AssetRow[] | null>(null);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const load = async () => {
    setLoading(true);
    setError('');
    try {
      const res = await apiFetch<{ items: AssetRow[] }>('/assets');
      setItems(res.items);
    } catch (e) {
      setItems(null);
      setError(e instanceof Error ? e.message : '读取失败');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (apiOnline && me && !me.isGuest) void load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [apiOnline, me]);

  const signedIn = Boolean(apiOnline && me && !me.isGuest);

  return (
    <>
      <div className="page-head">
        <div className="eyebrow">Workspace / Assets</div>
        <h1 className="page-title display">素材资产</h1>
        <p className="page-lede">视频、图片、音频、音乐、音效、字幕与声音档案。云端素材存放在 R2，键名强制以 workspace / user 前缀隔离。</p>
      </div>

      {!signedIn ? (
        <Callout>
          <strong>云端素材需要登录。</strong> 当前为访客本地模式：本机不会伪造云端素材列表，也无法访问任何其他用户的项目或文件。
          OAuth 凭据配置完成后，这里会显示你自己的素材。
        </Callout>
      ) : (
        <Callout neutral>
          <strong>已连接。</strong> 上传与下载都会在服务端校验键名前缀，前端隐藏不作为权限控制手段。
          <Button size="sm" style={{ marginLeft: 10 }} disabled={loading} onClick={() => void load()}>{loading ? '读取中…' : '刷新'}</Button>
        </Callout>
      )}

      {error ? <div style={{ color: 'var(--err)', fontSize: 12, marginBottom: 16 }}>{error}</div> : null}

      <SectionHead num="01" title="资产列表" aside={items ? `${items.length} 个文件` : '—'} />
      {!signedIn || items === null ? (
        <Empty
          title="没有可显示的素材"
          desc="这里不会插入示例视频、示例图片或伪造的生成状态。素材会在真实生成任务完成并上传后出现。"
        />
      ) : items.length === 0 ? (
        <Empty title="素材库为空" desc="尚未上传任何文件。生成任务完成后，视频与音频会按 workspace 前缀存入 R2 并在此列出。" />
      ) : (
        <div>
          {items.map((a) => (
            <div className="row" key={a.id}>
              <div className="row-main">
                <div className="row-name"><Pill>{a.kind}</Pill> {a.r2_key.split('/').slice(-1)[0]}</div>
                <div className="row-meta">{a.r2_key} · {a.byte_size} bytes · {a.mime_type ?? 'unknown'} · {a.created_at}</div>
              </div>
            </div>
          ))}
        </div>
      )}

      <div className="divider" />
      <SectionHead num="02" title="VOICE LAB · 声音档案" aside="Phase 4" />
      <Callout neutral>
        声音克隆必须由真正具备该能力的服务完成（例如 GPT-SoVITS、Fish Speech 或支持克隆的第三方 API），不能由 Opus 之类的文本模型冒充。
        若尚未配置声音克隆 Provider，工作流将使用「上传完整口播音频」的替代模式。声音样本需获得本人或授权人许可，用户必须能删除声音档案及关联数据。
        <div style={{ marginTop: 8 }}><Pill tone="warn">尚未实现</Pill></div>
      </Callout>

      <div className="notice">
        R2 键格式：ws/&lt;workspace_id&gt;/u/&lt;user_id&gt;/&lt;timestamp&gt;-&lt;filename&gt;。删除操作同时移除 D1 记录与 R2 对象。
      </div>
    </>
  );
}
