import { createContext, useCallback, useContext, useEffect, useMemo, useState, type ReactNode } from 'react';
import type { Identity, Project, ProviderConfig } from '../lib/types';
import { idbGet, idbSet, KV, STORE_KV } from '../lib/idb';
import { vault } from '../lib/vault';
import { listProjects, createProject, deleteProject, saveProject } from '../lib/localProjects';
import { getMe } from '../lib/apiClient';
import { getRuntimeConfig, setRuntimeConfig, RUNTIME_CHANGE_EVENT, type RuntimeConfig } from '../lib/runtime';

export type Route = 'home' | 'providers' | 'vault' | 'projects' | 'studio' | 'assets' | 'settings';

interface AppState {
  route: Route;
  navigate: (route: Route) => void;
  activeProjectId: string | null;
  openProject: (id: string) => void;
  providers: ProviderConfig[];
  saveProviders: (next: ProviderConfig[]) => Promise<void>;
  reloadProviders: () => Promise<void>;
  projects: Project[];
  newProject: (title?: string, script?: string) => Promise<Project>;
  updateProject: (project: Project) => Promise<void>;
  removeProject: (id: string) => Promise<void>;
  reloadProjects: () => Promise<void>;
  vaultReady: boolean;
  vaultExists: boolean;
  vaultUnlocked: boolean;
  refreshVault: () => Promise<void>;
  me: Identity | null;
  apiOnline: boolean;
  storageError: string | null;
  runtime: RuntimeConfig;
  setRuntime: (next: RuntimeConfig) => void;
  theme: 'light' | 'dark';
  setTheme: (t: 'light' | 'dark') => void;
}

const Ctx = createContext<AppState | null>(null);

export function AppProvider({ children }: { children: ReactNode }): JSX.Element {
  const [route, setRoute] = useState<Route>('home');
  const [activeProjectId, setActiveProjectId] = useState<string | null>(null);
  const [providers, setProviders] = useState<ProviderConfig[]>([]);
  const [projects, setProjects] = useState<Project[]>([]);
  const [vaultReady, setVaultReady] = useState(false);
  const [vaultExists, setVaultExists] = useState(false);
  const [vaultUnlocked, setVaultUnlocked] = useState(false);
  const [me, setMe] = useState<Identity | null>(null);
  const [apiOnline, setApiOnline] = useState(false);
  const [storageError, setStorageError] = useState<string | null>(null);
  const [theme, setThemeState] = useState<'light' | 'dark'>('light');
  const [runtime, setRuntimeState] = useState<RuntimeConfig>(() => getRuntimeConfig());

  const setRuntime = useCallback((next: RuntimeConfig) => {
    setRuntimeConfig(next);
    setRuntimeState(getRuntimeConfig());
  }, []);

  useEffect(() => {
    const sync = () => setRuntimeState(getRuntimeConfig());
    window.addEventListener(RUNTIME_CHANGE_EVENT, sync);
    return () => window.removeEventListener(RUNTIME_CHANGE_EVENT, sync);
  }, []);

  // IndexedDB can be unavailable (private mode, blocked storage, embedded
  // webviews). The app must still render and say so honestly, never hang on
  // an endless loading screen.
  const refreshVault = useCallback(async () => {
    try {
      // A hard timeout guarantees the app always becomes usable, even when
      // IndexedDB never resolves (some embedded/headless webviews).
      await Promise.race([
        vault.initialize(),
        new Promise<never>((_, reject) =>
          window.setTimeout(() => reject(new Error('本地存储初始化超时')), 3_000),
        ),
      ]);
    } catch (e) {
      setStorageError(e instanceof Error ? e.message : '本地存储不可用');
    }
    setVaultExists(vault.exists);
    setVaultUnlocked(vault.unlocked);
    setVaultReady(true);
  }, []);

  const reloadProviders = useCallback(async () => {
    const list = (await idbGet<ProviderConfig[]>(STORE_KV, KV.providers)) ?? [];
    setProviders(list);
  }, []);

  const saveProviders = useCallback(async (next: ProviderConfig[]) => {
    await idbSet(STORE_KV, KV.providers, next);
    setProviders(next);
  }, []);

  const reloadProjects = useCallback(async () => {
    setProjects(await listProjects());
  }, []);

  const newProject = useCallback(async (title?: string, script?: string) => {
    const p = await createProject(title ?? '未命名项目', script ?? '');
    await reloadProjects();
    return p;
  }, [reloadProjects]);

  const updateProject = useCallback(async (project: Project) => {
    await saveProject(project);
    await reloadProjects();
  }, [reloadProjects]);

  const removeProject = useCallback(async (id: string) => {
    await deleteProject(id);
    await reloadProjects();
  }, [reloadProjects]);

  const setTheme = useCallback((t: 'light' | 'dark') => {
    setThemeState(t);
    document.documentElement.setAttribute('data-theme', t);
    void idbSet(STORE_KV, KV.settings, { theme: t });
  }, []);

  useEffect(() => {
    void (async () => {
      try {
        await refreshVault();
      } catch {
        setVaultReady(true);
      }
      // Each local read is independent; one failure must not block the others.
      for (const task of [reloadProviders, reloadProjects]) {
        try { await task(); } catch (e) { setStorageError(e instanceof Error ? e.message : '本机数据读取失败'); }
      }
      try {
        const settings = await idbGet<{ theme?: 'light' | 'dark' }>(STORE_KV, KV.settings);
        if (settings?.theme) setTheme(settings.theme);
      } catch { /* ignore */ }
      try {
        const identity = await getMe();
        setMe(identity);
        setApiOnline(true);
      } catch {
        // Worker not running or offline: honest local-only mode, no fake cloud state.
        setMe(null);
        setApiOnline(false);
      }
    })();
  }, [refreshVault, reloadProviders, reloadProjects, setTheme]);

  const value = useMemo<AppState>(
    () => ({
      route,
      navigate: setRoute,
      activeProjectId,
      openProject: (id) => {
        setActiveProjectId(id);
        setRoute('studio');
      },
      providers,
      saveProviders,
      reloadProviders,
      projects,
      newProject,
      updateProject,
      removeProject,
      reloadProjects,
      vaultReady,
      vaultExists,
      vaultUnlocked,
      refreshVault,
      me,
      apiOnline,
      storageError,
      runtime,
      setRuntime,
      theme,
      setTheme,
    }),
    [route, activeProjectId, providers, saveProviders, reloadProviders, projects, newProject, updateProject, removeProject, reloadProjects, vaultReady, vaultExists, vaultUnlocked, refreshVault, me, apiOnline, storageError, runtime, setRuntime, theme, setTheme],
  );

  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

export function useApp(): AppState {
  const ctx = useContext(Ctx);
  if (!ctx) throw new Error('useApp must be used inside AppProvider');
  return ctx;
}
