/** Guest-mode project store. Local only — never syncs to any other user's cloud data. */

import { newId } from './crypto';
import { idbGet, idbSet, KV, STORE_KV } from './idb';
import { defaultBudget } from './cost';
import type { Project } from './types';

export async function listProjects(): Promise<Project[]> {
  const items = (await idbGet<Project[]>(STORE_KV, KV.projects)) ?? [];
  return [...items].sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
}

export async function getProject(id: string): Promise<Project | undefined> {
  return (await listProjects()).find((p) => p.id === id);
}

export async function createProject(title: string, script = ''): Promise<Project> {
  const now = new Date().toISOString();
  const project: Project = {
    id: newId('prj_'),
    title: title.trim() || '未命名项目',
    tool: 'ai-video-studio',
    status: 'draft',
    script,
    createdAt: now,
    updatedAt: now,
    owner: 'local',
    budget: defaultBudget(),
  };
  const all = await listProjects();
  await idbSet(STORE_KV, KV.projects, [project, ...all]);
  return project;
}

export async function saveProject(project: Project): Promise<void> {
  const all = await listProjects();
  const next = { ...project, updatedAt: new Date().toISOString() };
  const index = all.findIndex((p) => p.id === project.id);
  if (index === -1) all.unshift(next);
  else all[index] = next;
  await idbSet(STORE_KV, KV.projects, all);
}

export async function deleteProject(id: string): Promise<void> {
  const all = await listProjects();
  await idbSet(STORE_KV, KV.projects, all.filter((p) => p.id !== id));
}
