import { useEffect, useMemo, useState } from 'react';
import { useApp } from '../state/AppContext';
import { Button, Callout, Empty, Field, InlineStatus, Pill, SectionHead } from '../components/ui';
import { buildRequest } from '../lib/adapter';
import { proxyRequest } from '../lib/apiClient';
import { vault } from '../lib/vault';
import { buildPreflight, defaultBudget, formatEstimate } from '../lib/cost';
import { parseStoryboardResponse, preservesOriginalScript, SHOT_FIELDS, validateStoryboard, type Storyboard } from '../lib/schema';
import type { ProviderConfig } from '../lib/types';

const STAGES = [
  ['文稿理解', '文本模型'], ['AI 创意策划', '文本模型'], ['脚本分析', '文本模型'], ['分镜生成', '结构化 JSON'],
  ['声音合成', 'TTS / Voice Lab'], ['视频镜头生成', 'Video Provider'], ['自动字幕', '本地'], ['音画匹配', '时间线'],
  ['背景音乐', '素材'], ['音效', '素材'], ['时间线合成', 'WebCodecs / FFmpeg.wasm'], ['MP4 导出', '浏览器本地'], ['完整工程导出', '项目包'],
] as const;

function extractModelText(body: string): string {
  try {
    const j = JSON.parse(body) as Record<string, unknown>;
    const choices = j.choices as Array<{ message?: { content?: unknown } }> | undefined;
    if (choices?.[0]?.message && typeof choices[0].message.content === 'string') return choices[0].message.content;
    const content = j.content as Array<{ text?: unknown }> | undefined;
    if (Array.isArray(content) && typeof content[0]?.text === 'string') return content[0].text;
    if (typeof j.output_text === 'string') return j.output_text;
    if (typeof j.text === 'string') return j.text;
  } catch {
    /* fall through */
  }
  return body;
}

function download(filename: string, content: string): void {
  const url = URL.createObjectURL(new Blob([content], { type: 'text/plain;charset=utf-8' }));
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

export function VideoStudio(): JSX.Element {
  const { projects, activeProjectId, openProject, updateProject, providers, vaultUnlocked, apiOnline } = useApp();
  const project = useMemo(() => projects.find((p) => p.id === activeProjectId) ?? null, [projects, activeProjectId]);
  const [script, setScript] = useState('');
  const [loadedProjectId, setLoadedProjectId] = useState<string | null>(null);
  const [textProviderId, setTextProviderId] = useState('');
  const [videoProviderId, setVideoProviderId] = useState('');
  const [busy, setBusy] = useState(false);
  const [status, setStatus] = useState<{ text: string; tone: 'muted' | 'ok' | 'err' | 'warn' }>({ text: '', tone: 'muted' });
  const [rawResponse, setRawResponse] = useState('');

  // Load the script when a different project is opened; keep local edits otherwise.
  useEffect(() => {
    if (project && loadedProjectId !== project.id) {
      setScript(project.script);
      setLoadedProjectId(project.id);
    }
  }, [project, loadedProjectId]);

  const textProviders = providers.filter((p) => p.capabilities.includes('text') && p.enabled);
  const videoProviders = providers.filter((p) => p.capabilities.includes('video_generation') && p.enabled);
  const textProvider = textProviders.find((p) => p.id === textProviderId) ?? textProviders[0];
  const videoProvider = videoProviders.find((p) => p.id === videoProviderId) ?? videoProviders[0];
  const budget = project?.budget ?? defaultBudget();

  const saveScript = async () => {
    if (!project) return;
    await updateProject({ ...project, script });
    setStatus({ text: '文稿已保存到本机项目。原文完整保留，不会被模型擅自删改。', tone: 'ok' });
  };

  const updateBudget = async (patch: Partial<typeof budget>) => {
    if (!project) return;
    await updateProject({ ...project, budget: { ...budget, ...patch } });
  };

  const storyboardPrompt = (original: string, projectId: string): string =>
    `You are the AI director of SOL AI Studio. Produce STRICT JSON ONLY (no markdown, no explanation).\n` +
    `Schema: { "version":1, "project_id": <string>, "original_script": <string>, "generated_at": <ISO string>,\n` +
    `  "shots": [ { ${SHOT_FIELDS.map((f) => `"${f}": …`).join(', ')} } ] }\n\n` +
    `Rules:\n` +
    `- original_script MUST be a verbatim copy of the user's script. Never delete, summarise or rewrite any narration line.\n` +
    `- Each shot's narration_text is a contiguous portion of the original script; concatenated narration_text must contain every original line.\n` +
    `- sequence starts at 1 and is consecutive. estimated_duration is a positive number in seconds.\n` +
    `- reference_assets is an array of strings. video_provider / video_model / generated_asset are null.\n` +
    `- video_status must be "not_started". All other fields are strings (use "" when unknown).\n` +
    `- Do NOT invent capabilities. Do NOT output prose outside the JSON object.\n\n` +
    `project_id: ${projectId}\n\nUSER SCRIPT (verbatim):\n---\n${original}\n---`;

  const generateStoryboard = async () => {
    if (!project) return setStatus({ text: '请先创建或打开一个项目。', tone: 'warn' });
    if (!project.script.trim()) return setStatus({ text: '请先录入并保存口播文稿。', tone: 'warn' });
    if (!textProvider) return setStatus({ text: '没有已启用且标注了 text 能力的 Provider。请先在「我的 AI 模型」配置文本模型。', tone: 'warn' });
    if (!textProvider.modelId) return setStatus({ text: '所选文本 Provider 尚未填写 Model ID。', tone: 'warn' });
    if (!vaultUnlocked || !vault.hasSecret(textProvider.id)) return setStatus({ text: '请先解锁保险库，并确认该 Provider 已保存 API Key。', tone: 'warn' });
    if (!apiOnline) return setStatus({ text: 'Worker 代理不在线，无法发起真实上游请求。请启动本地 Worker 或部署后再试。', tone: 'warn' });

    const secret = vault.getSecret(textProvider.id);
    if (!secret) return setStatus({ text: '密钥不可用。', tone: 'err' });

    setBusy(true);
    setRawResponse('');
    setStatus({ text: `正在通过 ${textProvider.name} / ${textProvider.modelId} 发起真实请求…`, tone: 'muted' });
    try {
      const prompt = storyboardPrompt(project.script, project.id);
      const isAnthropic = textProvider.protocol === 'anthropic';
      const envelope = buildRequest(textProvider, secret.apiKey, {
        path: textProvider.endpoints.chat ?? (isAnthropic ? '/messages' : '/chat/completions'),
        body: isAnthropic
          ? { model: textProvider.modelId, max_tokens: 4096, messages: [{ role: 'user', content: prompt }] }
          : { model: textProvider.modelId, messages: [{ role: 'user', content: prompt }], temperature: 0.2, stream: false, ...textProvider.requestParams },
      });
      const response = await proxyRequest(envelope);
      setRawResponse(response.body.slice(0, 4000));

      if (response.transportError) throw new Error(`代理 / 网络失败：${response.transportError}`);
      if (!response.ok) throw new Error(`上游返回 HTTP ${response.status}：${response.body.slice(0, 300)}`);

      const parsed = parseStoryboardResponse(extractModelText(response.body));
      if (!parsed) throw new Error('模型返回的不是可解析的 JSON，已拒绝保存为分镜。');
      const validation = validateStoryboard(parsed);
      if (!validation.valid || !validation.storyboard) {
        throw new Error(`分镜未通过 Schema 校验：\n${validation.errors.slice(0, 8).join('\n')}`);
      }
      const sb: Storyboard = { ...validation.storyboard, original_script: project.script };
      const integrity = preservesOriginalScript(project.script, sb.shots);
      if (!integrity.preserved) {
        throw new Error(`模型删改了原始口播内容，已拒绝保存。缺失行数：${integrity.missing.length}。\n第一行：${integrity.missing[0] ?? ''}`);
      }
      await updateProject({ ...project, storyboard: sb, status: 'in_progress' });
      setStatus({ text: `真实生成成功：${sb.shots.length} 个镜头，已通过 18 字段 Schema 校验与原文完整性检查，并保存到项目。`, tone: 'ok' });
    } catch (e) {
      setStatus({ text: e instanceof Error ? e.message : '生成失败', tone: 'err' });
    } finally {
      setBusy(false);
    }
  };

  const preflight = textProvider
    ? buildPreflight(textProvider, { inputTokens: Math.ceil((project?.script.length ?? 0) / 2), outputTokens: 2000, requests: 1 }, budget, budget.spentConfirmed)
    : null;

  const exportAvailableFiles = () => {
    if (!project) return;
    download('project.json', JSON.stringify(project, null, 2));
    download('script.md', project.script);
    download('storyboard.json', JSON.stringify(project.storyboard ?? null, null, 2));
    download('metadata.json', JSON.stringify({ product: 'SOL AI', tool: 'ai-video-studio', exported_at: new Date().toISOString(), complete_bundle: false, note: 'Partial export: assets/, subtitles/, prompts/, exports/final.mp4 are not implemented in Phase 1.' }, null, 2));
    setStatus({ text: '已导出当前可用的 4 个文件。这不是完整工程包——素材、字幕、MP4 与重新导入将在 Phase 6 实现。', tone: 'warn' });
  };

  if (!project) {
    return (
      <>
        <div className="page-head">
          <div className="eyebrow">Applications / Phase 1</div>
          <h1 className="page-title display">AI VIDEO STUDIO</h1>
          <p className="page-lede">文稿到成片的自动化工作流。第一阶段已建立项目、模型契约、分镜 Schema、成本预检与预算结构。</p>
        </div>
        <Empty
          title="尚未打开项目"
          desc="从下面选择一个已有项目，或到「最近项目」新建一个。系统不会用示例数据伪装成真实工程。"
          action={<div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', justifyContent: 'center' }}>{projects.slice(0, 4).map((p) => <Button key={p.id} size="sm" onClick={() => openProject(p.id)}>{p.title}</Button>)}</div>}
        />
      </>
    );
  }

  return (
    <>
      <div className="page-head">
        <div className="eyebrow">Applications / AI Video Studio</div>
        <h1 className="page-title display">{project.title}</h1>
        <p className="page-lede">{project.id} · 本机项目 · 文稿 {project.script.length} 字符 · 更新于 {new Date(project.updatedAt).toLocaleString('zh-CN')}</p>
      </div>

      <Callout>
        <strong>第一阶段范围。</strong> 当前可用：项目与原始文稿保存、Provider 选择与能力校验、分镜 JSON Schema 与原文完整性校验、真实文本模型调用（需配置 Provider + 解锁保险库 + Worker 在线）、成本预检与预算。
        尚未实现：声音克隆、真实视频生成、字幕、多轨时间线、音画合成、MP4 导出、完整工程导入导出。下方不会用假状态冒充这些功能。
      </Callout>

      <SectionHead num="01" title="口播文稿" aside="原始文稿完整保留" />
      <Field label="Script" hint="AI 可以建议修改，但不得删除原文">
        <textarea className="textarea" rows={8} value={script} onChange={(e) => setScript(e.target.value)} placeholder="在这里粘贴或输入完整口播文稿…" />
      </Field>
      <div style={{ display: 'flex', gap: 9 }}>
        <Button variant="primary" onClick={() => void saveScript()}>保存文稿</Button>
        <span className="faint" style={{ fontSize: 11, alignSelf: 'center' }}>{script !== project.script ? '有未保存的修改' : '已保存'}</span>
      </div>

      <div className="divider" />

      <SectionHead num="02" title="模型与成本预检" aside="每次调用前显示" />
      <div className="grid-2" style={{ gap: '0 16px' }}>
        <Field label="文本 / 创意模型" hint="需标注 text 能力">
          <select className="select" value={textProvider?.id ?? ''} onChange={(e) => setTextProviderId(e.target.value)}>
            <option value="">— 无可用模型 —</option>
            {textProviders.map((p) => <option key={p.id} value={p.id}>{p.name} · {p.modelId || '未填 Model ID'}</option>)}
          </select>
        </Field>
        <Field label="视频模型" hint="需标注 video_generation 能力">
          <select className="select" value={videoProvider?.id ?? ''} onChange={(e) => setVideoProviderId(e.target.value)}>
            <option value="">— 无可用模型 —</option>
            {videoProviders.map((p) => <option key={p.id} value={p.id}>{p.name} · {p.modelId || '未填 Model ID'}</option>)}
          </select>
        </Field>
      </div>

      {preflight ? (
        <div className="result-box">
          {`当前 Provider : ${preflight.providerName}\n当前模型     : ${preflight.modelId}\n预计调用量   : 输入 ~${preflight.volume.inputTokens} tokens / 输出 ~${preflight.volume.outputTokens} tokens / 1 次请求\n预计费用     : ${formatEstimate(preflight.estimate)}\n${preflight.estimate.status === 'unknown' ? `              ${preflight.estimate.reason}\n` : ''}当前预算     : ${budget.projectLimit === null ? '未设上限' : `${budget.projectLimit} ${budget.currency}`}（单项目） / ${budget.perShotLimit === null ? '未设上限' : `${budget.perShotLimit} ${budget.currency}`}（单镜头）\n已确认花费   : ${budget.spentConfirmed} ${budget.currency}\n最大并发     : ${budget.maxConcurrentTasks} · 最大重试 ${budget.maxRetries} · ${budget.paused ? '已暂停' : '运行中'}\n是否继续     : ${preflight.blocked ? '被预算规则阻止' : '允许（仍需你点击确认）'}`}
          {preflight.reasons.length > 0 ? `\n提示         : ${preflight.reasons.join('；')}` : ''}
        </div>
      ) : (
        <Callout neutral>没有可用的文本 Provider，无法生成成本预检。费用不会被虚构为 0。</Callout>
      )}

      <div className="grid-4" style={{ marginTop: 16 }}>
        <Field label="单项目预算"><input className="input mono" type="number" min="0" value={budget.projectLimit ?? ''} placeholder="留空=不限" onChange={(e) => void updateBudget({ projectLimit: e.target.value === '' ? null : Number(e.target.value) })} /></Field>
        <Field label="单镜头预算"><input className="input mono" type="number" min="0" value={budget.perShotLimit ?? ''} placeholder="留空=不限" onChange={(e) => void updateBudget({ perShotLimit: e.target.value === '' ? null : Number(e.target.value) })} /></Field>
        <Field label="最大并发"><input className="input mono" type="number" min="1" max="30" value={budget.maxConcurrentTasks} onChange={(e) => void updateBudget({ maxConcurrentTasks: Math.max(1, Number(e.target.value)) })} /></Field>
        <Field label="最大重试"><input className="input mono" type="number" min="0" max="5" value={budget.maxRetries} onChange={(e) => void updateBudget({ maxRetries: Math.max(0, Number(e.target.value)) })} /></Field>
      </div>
      <label className="check"><input type="checkbox" checked={budget.paused} onChange={(e) => void updateBudget({ paused: e.target.checked })} /><span>暂停该项目全部任务</span></label>

      <div className="divider" />

      <SectionHead num="03" title="分镜生成" aside="真实上游调用 · 非模拟" />
      <div style={{ display: 'flex', gap: 9, alignItems: 'center', flexWrap: 'wrap' }}>
        <Button variant="primary" disabled={busy} onClick={() => void generateStoryboard()}>{busy ? '生成中…' : '生成分镜 JSON'}</Button>
        <Button onClick={exportAvailableFiles}>导出当前可用文件</Button>
        {project.storyboard ? <Pill tone="ok">已保存分镜</Pill> : <Pill tone="warn">尚无分镜</Pill>}
      </div>
      {status.text ? <InlineStatus text={status.text} tone={status.tone} /> : null}
      {rawResponse ? <div className="result-box">上游原始响应（已脱敏，截断）：{'\n'}{rawResponse}</div> : null}
      {project.storyboard ? <div className="result-box">{JSON.stringify(project.storyboard, null, 2).slice(0, 4000)}</div> : null}

      <div className="divider" />

      <SectionHead num="04" title="完整工作流状态" aside="13 步 · 诚实标注" />
      <div className="stage-list">
        {STAGES.map(([name, by], i) => (
          <div className="stage" key={name}>
            <span className="stage-n">{String(i + 1).padStart(2, '0')}</span>
            <div className="stage-b">
              <div className="stage-t">{name}</div>
              <div className="stage-d">{by}</div>
            </div>
            <Pill tone={i === 3 ? 'accent' : ''}>{i === 3 ? '条件可用' : '未实现'}</Pill>
          </div>
        ))}
      </div>

      <div className="notice">
        目标工程包结构（Phase 6）：project.json · script.md · storyboard.json · assets/{'{audio,video,images,music,effects}'} · subtitles/ · prompts/ · exports/final.mp4 · metadata.json。
        当前导出仅包含实际存在的文件，并明确标记 complete_bundle=false，不把部分文件冒充完整工程。
      </div>
    </>
  );
}
